            case AF_BACKEND_CPU: return "CPU";
            case AF_BACKEND_CUDA: return "CUDA";
            case AF_BACKEND_OPENCL: return "OpenCL";
            default: return "Unknown";
        }
    } catch (...) {
        return "Unknown";
    }
}

