bool IsNumericArrowType(arrow::Type::type type_id) {
    switch (type_id) {
        case arrow::Type::INT8:
        case arrow::Type::INT16:
        case arrow::Type::INT32:
        case arrow::Type::INT64:
        case arrow::Type::UINT8:
        case arrow::Type::UINT16:
        case arrow::Type::UINT32:
        case arrow::Type::UINT64:
        case arrow::Type::FLOAT:
        case arrow::Type::DOUBLE:
            return true;
        default:
            return false;
    }
}

std::string EscapeArffName(const std::string& value) {
    const bool needs_quotes =
        value.empty() ||
        value.find_first_of(" \t,{}%'\"") != std::string::npos;
    if (!needs_quotes) {
        return value;
    }

    std::string escaped = "'";
    for (char c : value) {
        if (c == '\'') {
            escaped += "\\'";
        } else {
            escaped.push_back(c);
        }
    }
    escaped.push_back('\'');
    return escaped;
}

std::string EscapeArffValue(const std::string& value) {
    const bool needs_quotes =
        value.empty() ||
        value.find_first_of(" \t,{}%'\"") != std::string::npos;
    if (!needs_quotes) {
        return value;
    }

    std::string escaped = "'";
    for (char c : value) {
        if (c == '\'') {
            escaped += "\\'";
        } else {
            escaped.push_back(c);
        }
    }
    escaped.push_back('\'');
    return escaped;
}

bool WriteArff(const std::shared_ptr<arrow::Table>& table,
               const DataConvertOptions& options,
