                lower.find("file") != std::string::npos ||
                lower.find("label") != std::string::npos ||
                lower.find("class") != std::string::npos ||
                lower.find("name") != std::string::npos) {
                likely_header = true;
                break;
            }

            // Check for typical header patterns
            bool is_numeric = !lower.empty();
            for (char c : lower) {
