        return false;
    }

    std::string list_str = it->second;
    list_str.erase(std::remove(list_str.begin(), list_str.end(), '['), list_str.end());
    list_str.erase(std::remove(list_str.begin(), list_str.end(), ']'), list_str.end());
    list_str.erase(std::remove(list_str.begin(), list_str.end(), ' '), list_str.end());

    indices.clear();
    std::stringstream ss(list_str);
    std::string token;
    while (std::getline(ss, token, ',')) {
        if (token.empty()) {
