        "_step_result = {"
        "'obs': _obs.tolist() if hasattr(_obs, 'tolist') else list(_obs),"
        "'reward': float(_reward),"
        "'done': bool(_terminated),"
        "'truncated': bool(_truncated)"
        "}\n"
