enum class MetricLearningPairLossKind {
    Contrastive,
    CosineEmbedding,
};

struct PairMetricLossResult {
    Tensor loss;
    Tensor grad_a;
    Tensor grad_b;
};

struct TripletMetricLossResult {
    Tensor loss;
    Tensor grad_anchor;
    Tensor grad_positive;
    Tensor grad_negative;
};

inline void ValidatePairLossInputs(const Tensor& embedding_a,
                                   const Tensor& embedding_b,
                                   const Tensor& labels,
                                   MetricLearningLabelConvention convention) {
    if (embedding_a.Shape() != embedding_b.Shape()) {

throw std::invalid_argument(
            "metric-learning pair loss embeddings must have identical shapes");
    }
    const auto& shape = embedding_a.Shape();
    const size_t pair_count = shape.empty() ? 0 : shape[0];
    if (pair_count == 0 || shape.size() < 2) {

throw std::invalid_argument(
            "metric-learning pair loss embeddings must be [batch, ...features]");
    }
    if (!TensorIsBatchVector(labels, pair_count)) {

throw std::invalid_argument(
            "metric-learning pair loss labels must be [batch] or [batch, 1]");
    }
    const float* label_data = labels.Data<float>();
    for (size_t row = 0; row < pair_count; ++row) {
        if (!IsValidMetricLearningLabel(
                convention, static_cast<double>(label_data[row]))) {

throw std::invalid_argument(
                "metric-learning pair loss label does not match convention");
        }
    }
}

inline PairMetricLossResult ComputePairMetricLoss(
    const Tensor& embedding_a,
    const Tensor& embedding_b,
    const Tensor& labels,
    MetricLearningPairLossKind kind,
    float margin,
    Reduction reduction = Reduction::Mean) {
    const auto convention =
        kind == MetricLearningPairLossKind::Contrastive
            ? MetricLearningLabelConvention::
                  ContrastiveZeroSimilarOneDissimilar
            : MetricLearningLabelConvention::
                  CosineOneSimilarNegativeOneDissimilar;
    ValidatePairLossInputs(embedding_a, embedding_b, labels, convention);

    PairMetricLossResult result;
    if (kind == MetricLearningPairLossKind::Contrastive) {
        ContrastiveLoss forward_loss(margin, reduction);
        forward_loss.SetLabels(labels);
        result.loss = forward_loss.Forward(embedding_a, embedding_b);
        result.grad_a = forward_loss.Backward(embedding_a, embedding_b);

        ContrastiveLoss swapped_loss(margin, reduction);
        swapped_loss.SetLabels(labels);
        (void)swapped_loss.Forward(embedding_b, embedding_a);
        result.grad_b = swapped_loss.Backward(embedding_b, embedding_a);
    } else {
        CosineEmbeddingLoss forward_loss(margin, reduction);
        forward_loss.SetLabels(labels);
        result.loss = forward_loss.Forward(embedding_a, embedding_b);
        result.grad_a = forward_loss.Backward(embedding_a, embedding_b);

        CosineEmbeddingLoss swapped_loss(margin, reduction);
        swapped_loss.SetLabels(labels);
        (void)swapped_loss.Forward(embedding_b, embedding_a);
        result.grad_b = swapped_loss.Backward(embedding_b, embedding_a);
    }

    return result;
}

inline void ValidateTripletLossInputs(const Tensor& anchor,
                                      const Tensor& positive,
                                      const Tensor& negative) {
    if (anchor.Shape() != positive.Shape() ||
        anchor.Shape() != negative.Shape()) {

throw std::invalid_argument(
            "metric-learning triplet loss embeddings must have identical shapes");
    }
    const auto& shape = anchor.Shape();
    if (shape.empty() || shape[0] == 0 || shape.size() < 2) {

throw std::invalid_argument(
            "metric-learning triplet loss embeddings must be [batch, ...features]");
    }
}

inline size_t TripletEmbeddingDim(const Tensor& embedding) {
    return embedding.NumElements() / embedding.Shape()[0];
}

inline TripletMetricLossResult ComputeEuclideanTripletMetricLoss(
    const Tensor& anchor,
    const Tensor& positive,
    const Tensor& negative,
    float margin,
    Reduction reduction = Reduction::Mean) {
    ValidateTripletLossInputs(anchor, positive, negative);

    TripletLoss loss(margin, TripletLoss::DistanceType::Euclidean, reduction);
    loss.SetNegative(negative);

    TripletMetricLossResult result;
    result.loss = loss.Forward(anchor, positive);
    result.grad_anchor = loss.Backward(anchor, positive);

    const auto& shape = anchor.Shape();
    const size_t batch_size = shape[0];
    const size_t dim = TripletEmbeddingDim(anchor);
    const float scale =
        reduction == Reduction::Mean ? 1.0f / static_cast<float>(batch_size)
                                     : 1.0f;

    std::vector<float> grad_positive(anchor.NumElements(), 0.0f);
    std::vector<float> grad_negative(anchor.NumElements(), 0.0f);
    const float* a = anchor.Data<float>();
    const float* p = positive.Data<float>();
    const float* n = negative.Data<float>();

    for (size_t row = 0; row < batch_size; ++row) {
        const size_t offset = row * dim;
        double dist_ap_sq = 0.0;
        double dist_an_sq = 0.0;
        for (size_t i = 0; i < dim; ++i) {
            const double ap = static_cast<double>(a[offset + i]) -
                              static_cast<double>(p[offset + i]);
            const double an = static_cast<double>(a[offset + i]) -
                              static_cast<double>(n[offset + i]);
            dist_ap_sq += ap * ap;
            dist_an_sq += an * an;
        }

        const double dist_ap = std::sqrt(dist_ap_sq);
        const double dist_an = std::sqrt(dist_an_sq);
        if (dist_ap - dist_an + static_cast<double>(margin) <= 0.0) {
            continue;
        }

        const double safe_ap = std::max(dist_ap, 1e-8);
        const double safe_an = std::max(dist_an, 1e-8);
        for (size_t i = 0; i < dim; ++i) {
            const size_t index = offset + i;
            grad_positive[index] =
                static_cast<float>((static_cast<double>(p[index]) -
                                    static_cast<double>(a[index])) /
                                   safe_ap) *
                scale;
            grad_negative[index] =
                static_cast<float>((static_cast<double>(a[index]) -
                                    static_cast<double>(n[index])) /
                                   safe_an) *
                scale;
        }
    }

    result.grad_positive = Tensor(shape, grad_positive.data());
    result.grad_negative = Tensor(shape, grad_negative.data());
    return result;
}

}  // namespace cyxwiz

struct PairMetricResult {
    size_t pair_count = 0;
    double threshold = 0.0;
    double accuracy = 0.0;
    double positive_distance_mean = 0.0;
    double negative_distance_mean = 0.0;
    size_t positive_count = 0;
    size_t negative_count = 0;
};

struct RetrievalMetricResult {
    size_t query_count = 0;
    size_t k = 0;
    double recall_at_k = 0.0;
    double mean_reciprocal_rank = 0.0;
    double nearest_neighbor_class_agreement = 0.0;
};

inline size_t FlattenedEmbeddingDim(const Tensor& embeddings) {
    const auto& shape = embeddings.Shape();
    if (shape.size() < 2 || shape[0] == 0) {

throw std::invalid_argument(
            "metric-learning embeddings must be [batch, ...features]");
    }
    return embeddings.NumElements() / shape[0];
}

inline double EuclideanDistanceRow(const Tensor& left,
                                   const Tensor& right,
                                   size_t row,
                                   size_t dim) {
    const float* left_data = left.Data<float>();
    const float* right_data = right.Data<float>();
    double sum = 0.0;
    const size_t offset = row * dim;
    for (size_t i = 0; i < dim; ++i) {
        const double diff = static_cast<double>(left_data[offset + i]) -
                            static_cast<double>(right_data[offset + i]);
        sum += diff * diff;
    }
    return std::sqrt(sum);
}

inline double EuclideanDistanceRows(const Tensor& embeddings,
                                    size_t left_row,
                                    size_t right_row,
                                    size_t dim) {
    const float* data = embeddings.Data<float>();
    double sum = 0.0;
    const size_t left_offset = left_row * dim;
    const size_t right_offset = right_row * dim;
    for (size_t i = 0; i < dim; ++i) {
        const double diff = static_cast<double>(data[left_offset + i]) -
                            static_cast<double>(data[right_offset + i]);
        sum += diff * diff;
    }
    return std::sqrt(sum);
}

inline bool PairLabelMeansSimilar(MetricLearningLabelConvention convention,
                                  double label) {
    if (!IsValidMetricLearningLabel(convention, label)) {

throw std::invalid_argument(
            "metric-learning pair label does not match convention");
    }
    switch (convention) {
        case MetricLearningLabelConvention::
            ContrastiveZeroSimilarOneDissimilar:
            return label == 0.0;
        case MetricLearningLabelConvention::
            CosineOneSimilarNegativeOneDissimilar:
            return label == 1.0;
        case MetricLearningLabelConvention::TripletNoLabels:

throw std::invalid_argument(
                "triplet label convention cannot score pair metrics");
    }
    return false;
}

inline PairMetricResult ComputePairDistanceMetrics(
    const Tensor& embedding_a,
    const Tensor& embedding_b,
    const Tensor& pair_label,
    MetricLearningLabelConvention convention,
    double threshold) {
    if (embedding_a.Shape() != embedding_b.Shape()) {

throw std::invalid_argument(
            "pair metric embeddings must have identical shapes");
    }

    const auto& shape = embedding_a.Shape();
    const size_t pair_count = shape.empty() ? 0 : shape[0];
    if (pair_count == 0) {

throw std::invalid_argument("pair metric embeddings cannot be empty");
    }
    if (!TensorIsBatchVector(pair_label, pair_count)) {

throw std::invalid_argument(
            "pair metric labels must be [batch] or [batch, 1]");
    }

    const size_t dim = FlattenedEmbeddingDim(embedding_a);
    const float* labels = pair_label.Data<float>();

    PairMetricResult result;
    result.pair_count = pair_count;
    result.threshold = threshold;

    size_t correct = 0;
    double positive_sum = 0.0;
    double negative_sum = 0.0;

    for (size_t row = 0; row < pair_count; ++row) {
        const double distance =
            EuclideanDistanceRow(embedding_a, embedding_b, row, dim);
        const bool similar = PairLabelMeansSimilar(
            convention, static_cast<double>(labels[row]));
        const bool predicted_similar = distance <= threshold;
        if (predicted_similar == similar) {
            ++correct;
        }
        if (similar) {
            positive_sum += distance;
            ++result.positive_count;
        } else {
            negative_sum += distance;
            ++result.negative_count;
        }
    }

    result.accuracy = static_cast<double>(correct) /
                      static_cast<double>(pair_count);
    result.positive_distance_mean =
        result.positive_count == 0
            ? 0.0
            : positive_sum / static_cast<double>(result.positive_count);
    result.negative_distance_mean =
        result.negative_count == 0
            ? 0.0
            : negative_sum / static_cast<double>(result.negative_count);
    return result;
}

inline int64_t ClassIdAt(const Tensor& class_ids, size_t row) {
    switch (class_ids.GetDataType()) {
        case DataType::Int64:
            return class_ids.Data<int64_t>()[row];
        case DataType::Int32:
            return static_cast<int64_t>(class_ids.Data<int32_t>()[row]);
        case DataType::Float32:
            return static_cast<int64_t>(class_ids.Data<float>()[row]);
        default:

throw std::invalid_argument(
                "retrieval class IDs must be Int64, Int32, or Float32");
    }
}

inline RetrievalMetricResult ComputeRetrievalMetrics(
    const Tensor& embeddings,
    const Tensor& class_ids,
    size_t k) {
    const auto& shape = embeddings.Shape();
    const size_t sample_count = shape.empty() ? 0 : shape[0];
    if (sample_count < 2) {

throw std::invalid_argument(
            "retrieval metrics require at least two embeddings");
    }
    if (k == 0) {

throw std::invalid_argument("retrieval k must be non-zero");
    }
    if (!TensorIsBatchVector(class_ids, sample_count)) {

throw std::invalid_argument(
            "retrieval class IDs must be [batch] or [batch, 1]");
    }

    const size_t dim = FlattenedEmbeddingDim(embeddings);
    const size_t effective_k = std::min(k, sample_count - 1);

    RetrievalMetricResult result;
    result.query_count = sample_count;
    result.k = effective_k;

    double recall_hits = 0.0;
    double reciprocal_rank_sum = 0.0;
    double nearest_match_sum = 0.0;

    for (size_t query = 0; query < sample_count; ++query) {
        std::vector<std::pair<double, size_t>> distances;
        distances.reserve(sample_count - 1);
        for (size_t candidate = 0; candidate < sample_count; ++candidate) {
            if (candidate == query) {
                continue;
            }
            distances.emplace_back(
                EuclideanDistanceRows(embeddings, query, candidate, dim),
                candidate);
        }
        std::sort(distances.begin(), distances.end(),
                  [](const auto& left, const auto& right) {
                      if (left.first == right.first) {
                          return left.second < right.second;
                      }
                      return left.first < right.first;
                  });

        const int64_t query_class = ClassIdAt(class_ids, query);
        size_t first_relevant_rank = 0;
        for (size_t rank = 0; rank < distances.size(); ++rank) {
            const size_t candidate = distances[rank].second;
            if (ClassIdAt(class_ids, candidate) == query_class) {
                first_relevant_rank = rank + 1;
                break;
            }
        }

        if (first_relevant_rank > 0 && first_relevant_rank <= effective_k) {
            recall_hits += 1.0;
        }
        if (first_relevant_rank > 0) {
            reciprocal_rank_sum +=
                1.0 / static_cast<double>(first_relevant_rank);
        }
        if (!distances.empty() &&
            ClassIdAt(class_ids, distances.front().second) == query_class) {
            nearest_match_sum += 1.0;
        }
    }

    const double denom = static_cast<double>(sample_count);
    result.recall_at_k = recall_hits / denom;
    result.mean_reciprocal_rank = reciprocal_rank_sum / denom;
    result.nearest_neighbor_class_agreement = nearest_match_sum / denom;
    return result;
}

}  // namespace cyxwiz

struct PairEmbeddings {
    Tensor embedding_a;
    Tensor embedding_b;
};

struct TripletEmbeddings {
    Tensor anchor;
    Tensor positive;
    Tensor negative;
};

struct PairBranchGradients {
    Tensor input_a;
    Tensor input_b;
};

struct TripletBranchGradients {
    Tensor anchor;
    Tensor positive;
    Tensor negative;
};

class SharedEncoderRuntime {
public:
    explicit SharedEncoderRuntime(std::unique_ptr<IExecutableModel> encoder)
        : encoder_(std::move(encoder)) {
        if (!encoder_) {

throw std::invalid_argument(
                "SharedEncoderRuntime requires an encoder");
        }
    }

    PairEmbeddings ForwardPair(const PairBatch& batch) {
        if (!batch.IsValid()) {

throw std::invalid_argument(
                "SharedEncoderRuntime requires a valid PairBatch");
        }
        ClearAccumulatedGradients();
        CacheSequentialPairInputs(batch);
        return {
            encoder_->Forward(batch.input_a),
            encoder_->Forward(batch.input_b),
        };
    }

    TripletEmbeddings ForwardTriplet(const TripletBatch& batch) {
        if (!batch.IsValid()) {

throw std::invalid_argument(
                "SharedEncoderRuntime requires a valid TripletBatch");
        }
        ClearAccumulatedGradients();
        CacheSequentialTripletInputs(batch);
        return {
            encoder_->Forward(batch.anchor),
            encoder_->Forward(batch.positive),
            encoder_->Forward(batch.negative),
        };
    }

    PairBranchGradients BackwardPair(const Tensor& grad_a,
                                     const Tensor& grad_b) {
        if (encoder_->AsSequentialModel() != nullptr) {
            return BackwardSequentialPair(grad_a, grad_b);
        }
        return {
            encoder_->Backward(grad_a),
            encoder_->Backward(grad_b),
        };
    }

    TripletBranchGradients BackwardTriplet(const Tensor& anchor_grad,
                                           const Tensor& positive_grad,
                                           const Tensor& negative_grad) {
        if (encoder_->AsSequentialModel() != nullptr) {
            return BackwardSequentialTriplet(
                anchor_grad, positive_grad, negative_grad);
        }
        return {
            encoder_->Backward(anchor_grad),
            encoder_->Backward(positive_grad),
            encoder_->Backward(negative_grad),
        };
    }

    void SetTraining(bool training) { encoder_->SetTraining(training); }

    std::map<std::string, Tensor> GetParameters() {
        return encoder_->GetParameters();
    }

    void SetParameters(const std::map<std::string, Tensor>& params) {
        encoder_->SetParameters(params);
    }

    std::map<std::string, Tensor> GetGradients() {
        if (has_accumulated_gradients_) {
            return accumulated_gradients_;
        }
        return encoder_->GetGradients();
    }

    void UpdateParameters(Optimizer* optimizer) {
        if (has_accumulated_gradients_) {
            if (optimizer == nullptr) {

throw std::invalid_argument(
                    "SharedEncoderRuntime accumulated gradient update requires an optimizer");
            }
            auto params = encoder_->GetParameters();
            optimizer->Step(params, accumulated_gradients_);
            encoder_->SetParameters(params);
            ClearAccumulatedGradients();
            return;
        }
        encoder_->UpdateParameters(optimizer);
    }

    IExecutableModel* Encoder() { return encoder_.get(); }
    const IExecutableModel* Encoder() const { return encoder_.get(); }

private:
    static bool IsReplayUnsafeTrainingModule(const Module& module) {
        if (!module.IsTraining()) {
            return false;
        }
        const std::string name = module.GetName();
        return name.rfind("Dropout", 0) == 0 ||
               name.rfind("BatchNorm", 0) == 0;
    }

    void EnsureSequentialReplaySupported(const char* mode) const {
        const auto* model = encoder_->AsSequentialModel();
        if (model == nullptr) {
            return;
        }
        for (size_t i = 0; i < model->Size(); ++i) {
            const Module* module = model->GetModule(i);
            if (module != nullptr && IsReplayUnsafeTrainingModule(*module)) {

throw std::logic_error(
                    std::string("SharedEncoderRuntime cannot replay ") +
                    mode +
                    " branches through training-mode stateful module " +
                    module->GetName() +
                    "; activation snapshots are required");
            }
        }
    }

    void CacheSequentialPairInputs(const PairBatch& batch) {
        if (encoder_->AsSequentialModel() == nullptr) {
            has_pair_cache_ = false;
            return;
        }
        EnsureSequentialReplaySupported("pair");
        pair_input_a_ = batch.input_a.Clone();
        pair_input_b_ = batch.input_b.Clone();
        has_pair_cache_ = true;
        has_triplet_cache_ = false;
    }

    void CacheSequentialTripletInputs(const TripletBatch& batch) {
        if (encoder_->AsSequentialModel() == nullptr) {
            has_triplet_cache_ = false;
            return;
        }
        EnsureSequentialReplaySupported("triplet");
        triplet_anchor_ = batch.anchor.Clone();
        triplet_positive_ = batch.positive.Clone();
        triplet_negative_ = batch.negative.Clone();
        has_triplet_cache_ = true;
        has_pair_cache_ = false;
    }

    static Tensor SumGradientTensor(const Tensor& left, const Tensor& right) {
        if (left.Shape() != right.Shape() ||
            left.GetDataType() != right.GetDataType()) {

throw std::logic_error(
                "SharedEncoderRuntime cannot accumulate mismatched gradients");
        }
        if (left.GetDataType() != DataType::Float32) {

throw std::logic_error(
                "SharedEncoderRuntime accumulated gradients require Float32 tensors");
        }

        std::vector<float> values(left.NumElements(), 0.0f);
        const float* left_data = left.Data<float>();
        const float* right_data = right.Data<float>();
        for (size_t i = 0; i < values.size(); ++i) {
            values[i] = left_data[i] + right_data[i];
        }
        return Tensor(left.Shape(), values.data(), DataType::Float32);
    }

    static std::map<std::string, Tensor> SumGradientMaps(
        const std::vector<std::map<std::string, Tensor>>& gradient_maps) {
        std::map<std::string, Tensor> summed;
        for (const auto& gradients : gradient_maps) {
            for (const auto& [name, gradient] : gradients) {
                auto it = summed.find(name);
                if (it == summed.end()) {
                    summed[name] = gradient.Clone();
                } else {
                    it->second = SumGradientTensor(it->second, gradient);
                }
            }
        }
        return summed;
    }

    PairBranchGradients BackwardSequentialPair(const Tensor& grad_a,
                                               const Tensor& grad_b) {
        EnsureSequentialReplaySupported("pair");
        if (!has_pair_cache_) {

throw std::logic_error(
                "SharedEncoderRuntime pair backward requires ForwardPair first");
        }

        (void)encoder_->Forward(pair_input_a_);
        Tensor input_grad_a = encoder_->Backward(grad_a);
        auto grad_map_a = encoder_->GetGradients();

        (void)encoder_->Forward(pair_input_b_);
        Tensor input_grad_b = encoder_->Backward(grad_b);
        auto grad_map_b = encoder_->GetGradients();

        accumulated_gradients_ = SumGradientMaps({grad_map_a, grad_map_b});
        has_accumulated_gradients_ = true;
        return {input_grad_a, input_grad_b};
    }

    TripletBranchGradients BackwardSequentialTriplet(
        const Tensor& anchor_grad,
        const Tensor& positive_grad,
        const Tensor& negative_grad) {
        EnsureSequentialReplaySupported("triplet");
        if (!has_triplet_cache_) {

throw std::logic_error(
                "SharedEncoderRuntime triplet backward requires ForwardTriplet first");
        }

        (void)encoder_->Forward(triplet_anchor_);
        Tensor input_grad_anchor = encoder_->Backward(anchor_grad);
        auto grad_map_anchor = encoder_->GetGradients();

        (void)encoder_->Forward(triplet_positive_);
        Tensor input_grad_positive = encoder_->Backward(positive_grad);
        auto grad_map_positive = encoder_->GetGradients();

        (void)encoder_->Forward(triplet_negative_);
        Tensor input_grad_negative = encoder_->Backward(negative_grad);
        auto grad_map_negative = encoder_->GetGradients();

        accumulated_gradients_ = SumGradientMaps(
            {grad_map_anchor, grad_map_positive, grad_map_negative});
        has_accumulated_gradients_ = true;
        return {input_grad_anchor, input_grad_positive, input_grad_negative};
    }

    void ClearAccumulatedGradients() {
        accumulated_gradients_.clear();
        has_accumulated_gradients_ = false;
    }

    std::unique_ptr<IExecutableModel> encoder_;
    Tensor pair_input_a_;
    Tensor pair_input_b_;
    Tensor triplet_anchor_;
    Tensor triplet_positive_;
    Tensor triplet_negative_;
    bool has_pair_cache_ = false;
    bool has_triplet_cache_ = false;
    bool has_accumulated_gradients_ = false;
    std::map<std::string, Tensor> accumulated_gradients_;
};

}  // namespace cyxwiz

struct PairMetricTrainingStepConfig {
    MetricLearningPairLossKind loss_kind =
        MetricLearningPairLossKind::Contrastive;
    float margin = 1.0f;
    Reduction reduction = Reduction::Mean;
    bool update_parameters = false;
};

struct TripletMetricTrainingStepConfig {
    float margin = 1.0f;
    Reduction reduction = Reduction::Mean;
    bool update_parameters = false;
};

struct PairMetricTrainingStepResult {
    Tensor loss;
    PairEmbeddings embeddings;
    PairBranchGradients input_gradients;
};

struct TripletMetricTrainingStepResult {
    Tensor loss;
    TripletEmbeddings embeddings;
    TripletBranchGradients input_gradients;
};

inline void ValidateMetricTrainingStepUpdate(bool update_parameters,
                                             Optimizer* optimizer) {
    if (update_parameters && optimizer == nullptr) {

throw std::invalid_argument(
            "metric-learning training step update requires an optimizer");
    }
}

inline PairMetricTrainingStepResult RunPairMetricTrainingStep(
    SharedEncoderRuntime& runtime,
    const PairBatch& batch,
    const PairMetricTrainingStepConfig& config,
    Optimizer* optimizer = nullptr) {
    if (!batch.IsValid()) {

throw std::invalid_argument(
            "pair metric training step requires a valid PairBatch");
    }
    ValidateMetricTrainingStepUpdate(config.update_parameters, optimizer);

    PairMetricTrainingStepResult result;
    result.embeddings = runtime.ForwardPair(batch);
    const auto loss = ComputePairMetricLoss(
        result.embeddings.embedding_a,
        result.embeddings.embedding_b,
        batch.pair_label,
        config.loss_kind,
        config.margin,
        config.reduction);
    result.loss = loss.loss;
    result.input_gradients =
        runtime.BackwardPair(loss.grad_a, loss.grad_b);
    if (config.update_parameters) {
        runtime.UpdateParameters(optimizer);
    }
    return result;
}

inline TripletMetricTrainingStepResult RunTripletMetricTrainingStep(
    SharedEncoderRuntime& runtime,
    const TripletBatch& batch,
    const TripletMetricTrainingStepConfig& config,
    Optimizer* optimizer = nullptr) {
    if (!batch.IsValid()) {

throw std::invalid_argument(
            "triplet metric training step requires a valid TripletBatch");
    }
    ValidateMetricTrainingStepUpdate(config.update_parameters, optimizer);

    TripletMetricTrainingStepResult result;
    result.embeddings = runtime.ForwardTriplet(batch);
    const auto loss = ComputeEuclideanTripletMetricLoss(
        result.embeddings.anchor,
        result.embeddings.positive,
        result.embeddings.negative,
        config.margin,
        config.reduction);
    result.loss = loss.loss;
    result.input_gradients = runtime.BackwardTriplet(
        loss.grad_anchor, loss.grad_positive, loss.grad_negative);
    if (config.update_parameters) {
        runtime.UpdateParameters(optimizer);
    }
    return result;
}

}  // namespace cyxwiz

ModelAnalysis ModelAnalyzer::AnalyzeGraph(
    const std::vector<gui::MLNode>& nodes,
    const std::vector<gui::NodeLink>& links,
    int batch_size
) {
    ModelAnalysis result;

    if (nodes.empty()) {
        result.error_message = "Graph is empty";
        return result;
    }

    // Get topological order
    std::vector<int> sorted_ids = TopologicalSort(nodes, links);
    if (sorted_ids.empty()) {
        result.error_message = "Graph has cycles or is not connected";
        return result;
    }

    // Find input shape from DatasetInput or first layer
    std::vector<size_t> current_shape;
    bool found_input = false;

    for (int node_id : sorted_ids) {
        const gui::MLNode* node = FindNodeById(node_id, nodes);
        if (!node) continue;

        if (node->type == gui::NodeType::DatasetInput) {
            // Try to get shape from node parameters
            int h = GetIntParam(*node, "height", 28);
            int w = GetIntParam(*node, "width", 28);
            int c = GetIntParam(*node, "channels", 1);
            current_shape = {static_cast<size_t>(h), static_cast<size_t>(w), static_cast<size_t>(c)};
            result.input_shape = current_shape;
            found_input = true;
            break;
        }
    }

    if (!found_input) {
        // Default to a common shape if no input node found
        current_shape = {28, 28, 1};  // MNIST default
        result.input_shape = current_shape;
    }

    // Analyze each layer in topological order
    for (int node_id : sorted_ids) {
        const gui::MLNode* node = FindNodeById(node_id, nodes);
        if (!node) continue;

        // Skip utility/data nodes
        if (IsUtilityNode(node->type)) continue;

        LayerAnalysis layer_analysis;
        layer_analysis.name = node->name;
        layer_analysis.type = node->type;
        layer_analysis.input_shape = current_shape;

        // Compute output shape
        std::vector<size_t> output_shape = InferOutputShape(*node, current_shape);
        layer_analysis.output_shape = output_shape;

        // Compute parameters
        if (IsModelLayer(node->type)) {
            switch (node->type) {
                case gui::NodeType::Dense: {
                    int64_t in_features = 1;
                    for (size_t dim : current_shape) in_features *= dim;
                    int64_t out_features = GetIntParam(*node, "units", 128);
                    bool bias = GetBoolParam(*node, "bias", true);
                    layer_analysis.parameters = ComputeDenseParams(in_features, out_features, bias);
                    layer_analysis.flops = ComputeDenseFLOPs(in_features, out_features, bias, batch_size);
                    break;
                }
                case gui::NodeType::Conv2D:
                case gui::NodeType::Conv1D:
                case gui::NodeType::Conv3D: {
                    int64_t in_channels = current_shape.size() >= 3 ? current_shape[2] : 1;
                    int64_t filters = GetIntParam(*node, "filters", 32);
                    int64_t kernel_size = GetIntParam(*node, "kernel_size", 3);
                    bool bias = GetBoolParam(*node, "bias", true);
                    layer_analysis.parameters = ComputeConv2DParams(in_channels, filters, kernel_size, bias);

                    int64_t out_h = output_shape.size() >= 1 ? output_shape[0] : 1;
                    int64_t out_w = output_shape.size() >= 2 ? output_shape[1] : 1;
                    int64_t in_h = current_shape.size() >= 1 ? current_shape[0] : 1;
                    int64_t in_w = current_shape.size() >= 2 ? current_shape[1] : 1;
                    layer_analysis.flops = ComputeConv2DFLOPs(in_h, in_w, in_channels, out_h, out_w, filters, kernel_size, batch_size);
                    break;
                }
                case gui::NodeType::BatchNorm:
                case gui::NodeType::LayerNorm:
                case gui::NodeType::GroupNorm:
                case gui::NodeType::InstanceNorm: {
                    int64_t features = current_shape.size() >= 3 ? current_shape[2] : (current_shape.empty() ? 1 : current_shape.back());
                    layer_analysis.parameters = ComputeBatchNormParams(features);
                    layer_analysis.non_trainable_params = ComputeBatchNormNonTrainableParams(features);
                    int64_t spatial_size = 1;
                    for (size_t i = 0; i < current_shape.size() - 1 && i < 2; ++i) {
                        spatial_size *= current_shape[i];
                    }
                    layer_analysis.flops = ComputeBatchNormFLOPs(features, spatial_size, batch_size);
                    break;
                }
                case gui::NodeType::LSTM:
                case gui::NodeType::GRU:
                case gui::NodeType::RNN: {
                    int64_t input_size = current_shape.empty() ? 1 : current_shape.back();
                    int64_t hidden_size = GetIntParam(*node, "hidden_size", 128);
                    int64_t seq_len = current_shape.size() >= 2 ? current_shape[0] : 1;
                    layer_analysis.parameters = ComputeLSTMParams(input_size, hidden_size);
                    layer_analysis.flops = ComputeLSTMFLOPs(input_size, hidden_size, seq_len, batch_size);
                    break;
                }
                case gui::NodeType::MultiHeadAttention:
                case gui::NodeType::SelfAttention:
                case gui::NodeType::CrossAttention: {
                    int64_t embed_dim = GetIntParam(*node, "embed_dim", 256);
                    int64_t num_heads = GetIntParam(*node, "num_heads", 8);
                    int64_t seq_len = current_shape.size() >= 2 ? current_shape[0] : 1;

}
                    layer_analysis.flops = ComputeBatchNormFLOPs(features, spatial_size, batch_size);
                    break;
                }
                case gui::NodeType::LSTM:
                case gui::NodeType::GRU:
                case gui::NodeType::RNN: {
                    int64_t input_size = current_shape.empty() ? 1 : current_shape.back();
                    int64_t hidden_size = GetIntParam(*node, "hidden_size", 128);
                    int64_t seq_len = current_shape.size() >= 2 ? current_shape[0] : 1;
                    layer_analysis.parameters = ComputeLSTMParams(input_size, hidden_size);
                    layer_analysis.flops = ComputeLSTMFLOPs(input_size, hidden_size, seq_len, batch_size);
                    break;
                }
                case gui::NodeType::MultiHeadAttention:
                case gui::NodeType::SelfAttention:
                case gui::NodeType::CrossAttention: {
                    int64_t embed_dim = GetIntParam(*node, "embed_dim", 256);
                    int64_t num_heads = GetIntParam(*node, "num_heads", 8);
                    int64_t seq_len = current_shape.size() >= 2 ? current_shape[0] : 1;
                    layer_analysis.parameters = ComputeAttentionParams(embed_dim, num_heads);
                    layer_analysis.flops = ComputeAttentionFLOPs(seq_len, embed_dim, num_heads, batch_size);
                    break;
                }
                case gui::NodeType::Embedding: {
                    int64_t vocab_size = GetIntParam(*node, "vocab_size", 10000);
                    int64_t embed_dim = GetIntParam(*node, "embed_dim", 256);
                    layer_analysis.parameters = vocab_size * embed_dim;
                    layer_analysis.flops = 0;  // Embedding is a lookup, no FLOPs
                    break;
                }
                default:
                    break;
            }
        }

        // Compute activation FLOPs
        if (IsActivation(node->type)) {
            int64_t elements = batch_size;
            for (size_t dim : current_shape) elements *= dim;
            layer_analysis.flops = ComputeActivationFLOPs(elements, node->type);
        }

        // Compute pooling FLOPs
        if (IsPooling(node->type)) {
            int64_t pool_size = GetIntParam(*node, "pool_size", 2);
            int64_t out_h = output_shape.size() >= 1 ? output_shape[0] : 1;
            int64_t out_w = output_shape.size() >= 2 ? output_shape[1] : 1;
            int64_t channels = current_shape.size() >= 3 ? current_shape[2] : 1;
            layer_analysis.flops = ComputePoolFLOPs(out_h, out_w, channels, pool_size, batch_size);
        }

        // Compute activation memory
        layer_analysis.memory_bytes = ComputeActivationMemory(output_shape, batch_size);

        // Add to results
        result.layers.push_back(layer_analysis);
        result.total_parameters += layer_analysis.parameters;
        result.trainable_parameters += layer_analysis.parameters;
        result.non_trainable_parameters += layer_analysis.non_trainable_params;
        result.total_flops += layer_analysis.flops;
        result.total_memory_bytes += layer_analysis.memory_bytes;

        // Update current shape for next layer
        current_shape = output_shape;
    }

    result.output_shape = current_shape;
    result.is_valid = true;
    return result;
}

std::string ModelAnalyzer::GenerateSummary(const ModelAnalysis& analysis) const {
    std::ostringstream oss;

    // Header
    oss << "Model Summary\n";

oss << std::string(80, '-') << "\n";

    // Layers
    for (const auto& layer : analysis.layers) {
        std::string type_name = GetNodeTypeName(layer.type);
        std::string display_name = layer.name.empty() ? type_name : layer.name + " (" + type_name + ")";
        if (display_name.length() > 24) {
            display_name = display_name.substr(0, 21) + "...";
        }

oss << std::string(80, '=') << "
";
    oss << "Total params: " << FormatParameterCount(analysis.total_parameters) << "
";
    oss << "Trainable params: " << FormatParameterCount(analysis.trainable_parameters) << "
";
    oss << "Non-trainable params: " << FormatParameterCount(analysis.non_trainable_parameters) << "
";
    oss << "Total FLOPs: " << FormatFLOPs(analysis.total_flops) << "
";
    oss << "Estimated memory: " << FormatMemory(analysis.total_memory_bytes) << "
";

oss << std::string(80, '-') << "\n";
    oss << "Input shape: " << FormatShape(analysis.input_shape) << "\n";
    oss << "Output shape: " << FormatShape(analysis.output_shape) << "\n";

    return oss.str();
}

std::string ModelAnalyzer::ExportToJson(const ModelAnalysis& analysis) const {
    nlohmann::json j;

    j["is_valid"] = analysis.is_valid;
    j["error_message"] = analysis.error_message;
    j["total_parameters"] = analysis.total_parameters;
    j["trainable_parameters"] = analysis.trainable_parameters;
    j["non_trainable_parameters"] = analysis.non_trainable_parameters;
    j["total_flops"] = analysis.total_flops;
    j["total_memory_bytes"] = analysis.total_memory_bytes;
    j["input_shape"] = analysis.input_shape;
    j["output_shape"] = analysis.output_shape;

    nlohmann::json layers_json = nlohmann::json::array();
    for (const auto& layer : analysis.layers) {
        nlohmann::json layer_json;
        layer_json["name"] = layer.name;
        layer_json["type"] = GetNodeTypeName(layer.type);
        layer_json["input_shape"] = layer.input_shape;
        layer_json["output_shape"] = layer.output_shape;
        layer_json["parameters"] = layer.parameters;
        layer_json["non_trainable_params"] = layer.non_trainable_params;
        layer_json["flops"] = layer.flops;
        layer_json["memory_bytes"] = layer.memory_bytes;
        layers_json.push_back(layer_json);
    }
    j["layers"] = layers_json;

    return j.dump(2);
}

// ===== Helper Methods =====

std::vector<int> ModelAnalyzer::TopologicalSort(
    const std::vector<gui::MLNode>& nodes,
    const std::vector<gui::NodeLink>& links
) const {
    std::map<int, int> in_degree;
    std::map<int, std::vector<int>> adjacency;

    // Initialize
    for (const auto& node : nodes) {
        in_degree[node.id] = 0;
        adjacency[node.id] = {};
    }

    // Build adjacency list and compute in-degrees
    for (const auto& link : links) {
        adjacency[link.from_node].push_back(link.to_node);
        in_degree[link.to_node]++;
    }

    // Kahn's algorithm
    std::queue<int> queue;
    for (const auto& [id, degree] : in_degree) {
        if (degree == 0) queue.push(id);
    }

    std::vector<int> result;
    while (!queue.empty()) {
        int node_id = queue.front();
        queue.pop();
        result.push_back(node_id);

        for (int neighbor : adjacency[node_id]) {
            in_degree[neighbor]--;
            if (in_degree[neighbor] == 0) {
                queue.push(neighbor);
            }
        }
    }

    // Check for cycles
    if (result.size() != nodes.size()) {
        return {};  // Graph has cycles
    }

    return result;
}

const gui::MLNode* ModelAnalyzer::FindNodeById(int id, const std::vector<gui::MLNode>& nodes) const {
    for (const auto& node : nodes) {
        if (node.id == id) return &node;
    }
    return nullptr;
}

std::vector<int> ModelAnalyzer::GetInputNodeIds(
    int to_node_id,
    const std::vector<gui::NodeLink>& links
) const {
    std::vector<int> inputs;
    for (const auto& link : links) {
        if (link.to_node == to_node_id) {
            inputs.push_back(link.from_node);
        }
    }
    return inputs;
}

