                        if (p["name"] == "weight" && p.contains("shape")) {
                            auto shape = p["shape"];
                            if (shape.size() >= 2) {
                                int in_features = shape[1].get<int>();
                                input_node["parameters"]["shape"] = "[" + std::to_string(in_features) + "]";
                                spdlog::info("    Inferred input shape: [{}]", in_features);
                                break;
                            }
