enum class ModelFormat {
    CyxModel,       // .cyxmodel - Native complete format (ZIP archive)
    ONNX,           // .onnx - ONNX interchange format
    Safetensors,    // .safetensors - Safe tensor serialization
    GGUF,           // .gguf - GGML Universal Format for LLMs
    Unknown
};

