};

/**
 * DBSCANOperator — Density-Based Spatial Clustering.
 *
 * Params:
 *   feature_cols (optional, comma-sep)
 *   label_col    (optional)
 *   eps          (default 0.5)          — neighborhood radius.
 *   min_samples  (default 5)            — core-point threshold.
