    std::string value = TrimString(scalar->ToString());
    if (value.size() >= 2 && value.front() == '"' && value.back() == '"') {
        value = value.substr(1, value.size() - 2);
    }
    return TrimString(value);
}

std::string QuoteSqlIdentifier(const std::string& identifier) {
    std::string quoted = "\"";
    for (char c : identifier) {
        if (c == '"') {
            quoted += "\"\"";
        } else {
            quoted += c;
        }
    }
    quoted += '"';
    return quoted;
}

std::string QuoteSqlStringLiteral(const std::string& value) {
    std::string quoted = "'";
    for (char c : value) {
        if (c == '\'') {
            quoted += "''";
        } else {
            quoted += c;
        }
    }
    quoted += "'";
    return quoted;
}

std::string QuoteJsonString(const std::string& value) {
    std::string quoted = "\"";
    const char* hex = "0123456789abcdef";
    for (unsigned char c : value) {
        switch (c) {
        case '"':
            quoted += "\\\"";
            break;
        case '\\':
            quoted += "\\\\";
            break;
        case '\b':
            quoted += "\\b";
            break;
        case '\f':
            quoted += "\\f";
            break;
        case '\n':
            quoted += "\\n";
            break;
        case '\r':
            quoted += "\\r";
            break;
        case '\t':
            quoted += "\\t";
            break;
        default:
            if (c < 0x20) {
                quoted += "\\u00";
                quoted.push_back(hex[(c >> 4) & 0x0f]);
                quoted.push_back(hex[c & 0x0f]);
            } else {
                quoted.push_back(static_cast<char>(c));
            }
            break;
        }
    }
    quoted += '"';
    return quoted;
}

