std::string PipelineExecutor::GetInputDatasetName(const Node& node, ExecutionContext& ctx) {
    const auto input_dataset_names = GetInputDatasetNames(node, ctx, 1);
    if (input_dataset_names.empty()) {
        return "";
    }
