                   std::to_string(i) + ") OVER (ORDER BY rowid) AS " +
                   QuoteSqlIdentifier(columns + "_diff" + std::to_string(i));
        }
        sql += " FROM " + temp_table;

        auto result_table = duckdb_->Query(sql);
        duckdb_->UnregisterTable(temp_table);

