MaterializeTableResult PipelineMaterializer::MaterializeTable(
    const std::vector<gui::MLNode>& nodes,
    const std::vector<gui::NodeLink>& links,
    const std::shared_ptr<arrow::Table>& source_table,
    const std::string& source_dataset_name,
    PipelineOperatorProgressCallback progress_callback) {

    MaterializeTableResult result;
    result.table = source_table;

    if (!source_table) {
        result.success = false;
        result.error_message = "PipelineMaterializer: source Arrow table is null";
        return result;
    }

    const gui::MLNode* data_input = FindDataInputNode(nodes, source_dataset_name);
    if (!data_input) {
        if (!source_dataset_name.empty()) {
            result.success = false;
            result.error_message =
                "PipelineMaterializer: source dataset '" +
                source_dataset_name +
                "' does not match any DataInput/DatasetInput node";
        }
        return result;
    }

    auto& factory = PipelineOperatorFactory::Instance();

    bool any_materializable = false;
    for (const auto& n : nodes) {
        if (n.id == data_input->id) continue;
        if (IsArrowTableMaterializerOperator(n.type)) {
            any_materializable = true;
            break;
        }
    }
    if (!any_materializable) {
        return result;
    }

    std::string graph_shape_error;
    if (!ValidateLinearMaterializerOperatorPath(
            *data_input, nodes, links, graph_shape_error)) {
        result.success = false;
        result.error_message = graph_shape_error;
        return result;
    }

    auto current_table = source_table;
    std::queue<int> queue;
    std::unordered_set<int> visited;
    queue.push(data_input->id);
    visited.insert(data_input->id);

    while (!queue.empty()) {
        const int node_id = queue.front();
        queue.pop();

        const gui::MLNode* node = FindNodeById(node_id, nodes);
        if (!node) continue;

        const auto operator_type =
            ResolveArrowTableMaterializerOperatorType(node->type);
        if (node->id != data_input->id && operator_type.has_value()) {
            auto op = factory.Create(*operator_type);
            if (!op) {
                result.success = false;
                result.error_message =
                    "PipelineMaterializer: factory returned null for node '" +
                    node->name +
                    "' (runtime support allows materialization but Create failed)";
                return result;
            }

            op->SetProgressCallback(
                [progress_callback, node](const PipelineOperatorProgress& event) {
                    if (!progress_callback) {
                        return;
                    }
                    auto with_node = event;
                    with_node.node_id = node->id;
                    with_node.node_name = node->name;
                    progress_callback(with_node);
                });

            std::string err;
            auto params = BuildOperatorParams(*node, nodes, links);
            if (!op->Configure(params, err)) {
                result.success = false;
                result.error_message =
                    "PipelineMaterializer: Configure failed for node '" +
                    node->name + "': " + err;
                return result;
            }

            auto applied = op->Apply(current_table);
            if (!applied.ok()) {
                result.success = false;
                result.error_message =
                    "PipelineMaterializer: Apply failed for node '" +
                    node->name + "': " + applied.status().message();
                return result;
            }

            current_table = applied.ValueOrDie();
            ++result.operators_applied;
            spdlog::info("PipelineMaterializer: applied operator '{}' on node '{}'",
                         op->GetName(), node->name);
        }

        for (const auto& link : links) {
            if (link.from_node == node_id &&
                visited.insert(link.to_node).second) {
                queue.push(link.to_node);
            }
        }
    }

result.error_message =
                    "PipelineMaterializer: Apply failed for node '" +
                    node->name + "': " + applied.status().message();
                return result;
            }

            current_table = applied.ValueOrDie();
            ++result.operators_applied;
            spdlog::info("PipelineMaterializer: applied operator '{}' on node '{}'",
                         op->GetName(), node->name);
        }

        for (const auto& link : links) {
            if (link.from_node == node_id &&
                visited.insert(link.to_node).second) {
                queue.push(link.to_node);
            }
        }
    }

    result.table = current_table;

class PrefetchBatcher final : public IBatcher {
public:
    PrefetchBatcher(IBatcher& source, size_t queue_depth, std::string name)
        : source_(source)
        , queue_depth_(std::max<size_t>(1, queue_depth))
        , name_(std::move(name)) {}

    ~PrefetchBatcher() override {
        StopWorker();
    }

    Batch GetNextBatch() override {
        StartWorker();

        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_cv_.wait(lock, [this]() {
            return stop_requested_ || !queue_.empty() || source_complete_;
        });

        if (queue_.empty()) {
            return {};
        }

        Batch batch = std::move(queue_.front());
        queue_.pop();
        lock.unlock();
        not_full_cv_.notify_one();
        return batch;
    }

    void Reset() override {
        StopWorker();
        source_.Reset();

        std::lock_guard<std::mutex> lock(mutex_);
        source_complete_ = false;
        started_ = false;
        ClearQueue();
    }

    bool IsEpochComplete() const override {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!started_) {
            return source_.IsEpochComplete();
        }
        return source_complete_ && queue_.empty();
    }

    size_t GetNumBatches() const override { return source_.GetNumBatches(); }
    size_t GetNumSamples() const override { return source_.GetNumSamples(); }

    void SetNormalization(float mean, float std_dev) override {
        StopWorker();
        source_.SetNormalization(mean, std_dev);
    }

    void SetOneHotEncoding(size_t num_classes) override {
        StopWorker();
        source_.SetOneHotEncoding(num_classes);
    }

    void SetFlatten(bool flatten) override {
        StopWorker();
        source_.SetFlatten(flatten);
    }

    void SetPhase(BatcherPhase phase) override {
        StopWorker();
        source_.SetPhase(phase);
    }

private:
    void StartWorker() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (started_) {
            return;
        }

        stop_requested_ = false;
        source_complete_ = false;
        started_ = true;
        worker_ = std::thread([this]() { WorkerLoop(); });
        spdlog::info("PrefetchBatcher '{}': started async queue with depth={}",
                     name_, queue_depth_);
    }

    void StopWorker() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stop_requested_ = true;
        }
        not_empty_cv_.notify_all();
        not_full_cv_.notify_all();

        if (worker_.joinable()) {
            worker_.join();
        }

        std::lock_guard<std::mutex> lock(mutex_);
        stop_requested_ = false;
        started_ = false;
        source_complete_ = false;
        ClearQueue();
    }

    void WorkerLoop() {
        while (true) {
            {
                std::unique_lock<std::mutex> lock(mutex_);
