struct TrainingMetrics {
    // Current progress
    int current_epoch = 0;
    int total_epochs = 0;
    int current_batch = 0;
    int total_batches = 0;
    int optimizer_step_count = 0;
    size_t train_sample_count = 0;
    size_t val_sample_count = 0;
    size_t test_sample_count = 0;

    // Training metrics
    float train_loss = 0.0f;
    float train_accuracy = 0.0f;

    // Validation metrics
    float val_loss = 0.0f;
    float val_accuracy = 0.0f;
    bool has_validation_metrics = false;

    // Held-out test metrics, populated after training when a test split exists.
    float test_loss = 0.0f;
    float test_accuracy = 0.0f;
    bool has_test_metrics = false;

    // Checkpoint actually restored/used for final evaluation. Empty means no
    // concrete checkpoint path was restored by the executor.
    std::string checkpoint_used;

    // Token-level sequence tagging metrics. For sequence training,
    // train_accuracy/val_accuracy also mirror token accuracy so existing
    // dashboards and callbacks keep working.
    float train_token_accuracy = 0.0f;
    float val_token_accuracy = 0.0f;
    float train_entity_f1 = 0.0f;
    float val_entity_f1 = 0.0f;
    size_t train_token_count = 0;
    size_t val_token_count = 0;

    // Timing
    float epoch_time_seconds = 0.0f;
    float samples_per_second = 0.0f;

    // State
    bool is_training = false;
    bool is_paused = false;
    bool is_complete = false;
    std::string status_message;
    std::string terminal_status;
    std::string terminal_reason;

    // History (for plotting)
    std::vector<float> loss_history;
    std::vector<float> accuracy_history;
    std::vector<float> val_loss_history;
    std::vector<float> val_accuracy_history;
};

/**
 * Callback types for training progress
 */
using BatchCallback = std::function<void(int epoch, int batch, int total_batches,
                                           float loss, float accuracy)>;
using EpochCallback = std::function<void(int epoch, float train_loss, float train_acc,
                                          float val_loss, float val_acc, float epoch_time)>;
using TrainingCompleteCallback = std::function<void(const TrainingMetrics& final_metrics)>;

/**
 * TrainingExecutor - Executes ML training based on compiled graph configuration
 *
 * This class handles the actual training loop:
 * - Builds the model DYNAMICALLY from TrainingConfiguration
 * - Creates optimizer based on config
 * - Iterates over batches
 * - Performs forward/backward passes
 * - Updates weights
 * - Reports progress via callbacks
 */

class TrainingExecutor {
public:
    /**
     * Create a training executor
     * @param config Compiled training configuration from GraphCompiler
     * @param dataset Dataset handle from DataRegistry
     */
    TrainingExecutor(TrainingConfiguration config, DatasetHandle dataset);

    /**
     * Create a training executor with Arrow dataset (modern API)
     * @param config Compiled training configuration from GraphCompiler
     * @param arrow_dataset Arrow dataset with features and labels
     * @param label_column Name of the label column
     */
    TrainingExecutor(TrainingConfiguration config,
                     std::shared_ptr<ArrowDataset> arrow_dataset,
                     const std::string& label_column);

    /**
     * Create a training executor for a disk-backed Parquet dataset.
     * Used when DataRegistry::LoadTabularCSV picked the disk-backed path
     * because the CSV was too big to fit in RAM.
     */
    TrainingExecutor(TrainingConfiguration config,
                     std::shared_ptr<ParquetBackedDataset> parquet_dataset,
                     const std::string& label_column);

    TrainingExecutor(TrainingConfiguration config,
                     std::unique_ptr<IBatcher> external_batcher);

    TrainingExecutor(TrainingConfiguration config,
                     std::unique_ptr<ISequenceBatcher> sequence_batcher,
                     std::vector<std::string> id_to_label);

    ~TrainingExecutor();

    /**
     * Start training (blocking - should be called from a background thread)
     * @param epochs Number of epochs to train
     * @param batch_size Batch size
     * @param batch_cb Callback for each batch (optional)
     * @param epoch_cb Callback for each epoch (optional)
     * @param complete_cb Callback when training completes (optional)
     */
    void Train(
        int epochs,
        int batch_size,
        BatchCallback batch_cb = nullptr,
        EpochCallback epoch_cb = nullptr,
        TrainingCompleteCallback complete_cb = nullptr
    );

    /**
     * Stop training (thread-safe, cooperative cancellation)
     */
    void Stop();

    /**
     * Pause training (thread-safe)
     */
    void Pause();

    /**
     * Resume training after pause (thread-safe)
     */
    void Resume();

    /**
     * Check if training is currently running
     */
    bool IsTraining() const { return is_training_.load(); }

    /**
     * Check if training is paused
     */
    bool IsPaused() const { return is_paused_.load(); }

    /**
     * Get current training metrics (thread-safe)
     */
    TrainingMetrics GetMetrics() const;

    /**
     * Get the training configuration
     */
    const TrainingConfiguration& GetConfig() const { return config_; }

    /**
     * Get the trained model (for export)
     */
    SequentialModel* GetModel() {
        return model_ ? model_->AsSequentialModel() : nullptr;
    }

    /**
     * Get the optimizer (for export)
     */
    Optimizer* GetOptimizer() { return optimizer_.get(); }

    /**
     * Release ownership of the model (transfers ownership to caller)
     */
    std::unique_ptr<SequentialModel> ReleaseModel() {
        return model_ ? model_->ReleaseSequentialModel() : nullptr;
    }

    /**
     * Release ownership of the optimizer (transfers ownership to caller)
     */
    std::unique_ptr<Optimizer> ReleaseOptimizer() { return std::move(optimizer_); }

private:
    // Three possible dataset backings. Exactly one of dataset_ / arrow_dataset_ /
    // parquet_dataset_ is populated at construction time, based on which
    // constructor was called. mode_ is the tag the Train() function uses
    // to pick the right batcher implementation.

enum class DatasetMode {
        Legacy,   // DatasetHandle + legacy DatasetBatcher
        Arrow,    // ArrowDataset + ArrowDatasetBatcher
        External, // Image/Audio/Text IBatcher constructed by TrainingManager
        SequenceExternal, // Token-tagging ISequenceBatcher constructed upstream
        Parquet   // ParquetBackedDataset + ParquetArrowBatcher (disk-backed)
    };

    TrainingConfiguration config_;
    DatasetHandle dataset_;
    std::shared_ptr<ArrowDataset> arrow_dataset_;
    std::shared_ptr<ParquetBackedDataset> parquet_dataset_;
    std::string label_column_;
    DatasetMode mode_ = DatasetMode::Legacy;
    std::unique_ptr<IBatcher> external_batcher_;
    std::unique_ptr<ISequenceBatcher> sequence_batcher_;
    std::vector<std::string> sequence_id_to_label_;

    // Thread safety
    std::atomic<bool> is_training_{false};
    std::atomic<bool> stop_requested_{false};
    std::atomic<bool> is_paused_{false};

    mutable std::mutex metrics_mutex_;
    TrainingMetrics metrics_;

    // Training components - DYNAMIC MODEL
    std::unique_ptr<IExecutableModel> model_;
    std::unique_ptr<Optimizer> optimizer_;
    std::unique_ptr<Loss> loss_;  // Unified loss function (MSE, CrossEntropy, BCE, etc.)

    // Internal training methods

    /**
     * Initialize the training components by building model from config
     */
    bool Initialize(int batch_size);

    /**
     * Run a single training epoch
     */
    void RunTrainingEpoch(
        DatasetBatcher& batcher,
        int epoch,
        BatchCallback batch_cb
    );

    /**
     * Run validation
     */
    void RunValidation(DatasetBatcher& batcher);

    /**
     * Run a single training epoch through any IBatcher implementation.
     * Used for both ArrowDatasetBatcher (in-memory) and ParquetArrowBatcher
     * (disk-backed) — polymorphism via IBatcher lets the same loop drive
     * either one. Name kept as *Arrow for backwards compat with callers
     * that haven't been renamed yet; the implementation is batcher-agnostic.
     */
    void RunTrainingEpochArrow(
        IBatcher& batcher,
        int epoch,
        BatchCallback batch_cb
    );

    /**
     * Run validation through any IBatcher implementation.
     */
    void RunValidationArrow(IBatcher& batcher);
    std::pair<float, float> EvaluateArrowBatcher(IBatcher& batcher);

    /**
     * Run a single token-tagging epoch through an ISequenceBatcher.
     */
    void RunTrainingEpochSequence(
        ISequenceBatcher& batcher,
        int epoch,
        BatchCallback batch_cb
    );

    /**
     * Run validation for token-tagging batches.
     */
    void RunValidationSequence(ISequenceBatcher& batcher);

    /**
     * Forward pass through the model
     * @param input Input tensor [batch_size, input_features]
     * @return Output tensor [batch_size, num_classes]
     */
    Tensor Forward(const Tensor& input);

    /**
     * Compute loss between predictions and targets
     */
    float ComputeLoss(const Tensor& predictions, const Tensor& targets);

    /**
     * Compute accuracy (for classification)
     */
    float ComputeAccuracy(const Tensor& predictions, const Tensor& targets);

    /**
     * Backward pass through the model
     */
    void Backward(const Tensor& predictions, const Tensor& targets);

    /**
     * Accumulate current model gradients and step optimizer at the configured
     * grad_accum_steps boundary, or when force_step is true for a final partial
     * accumulation window.
     */
    bool AccumulateGradientsAndMaybeStep(
        int epoch,
        int batch_num,
        int total_batches,
        float batch_loss,
        float current_acc,
        bool force_step
    );

float ComputeAccuracy(const Tensor& predictions, const Tensor& targets);

    /**
     * Backward pass through the model
     */
    void Backward(const Tensor& predictions, const Tensor& targets);

    /**
     * Accumulate current model gradients and step optimizer at the configured
     * grad_accum_steps boundary, or when force_step is true for a final partial
     * accumulation window.
     */
    bool AccumulateGradientsAndMaybeStep(
        int epoch,
        int batch_num,
        int total_batches,
        float batch_loss,
        float current_acc,
        bool force_step
    );

TrainingManager& TrainingManager::Instance() {
    static TrainingManager instance;
    return instance;
}

TrainingManager::~TrainingManager() {
    StopTraining();
    if (training_thread_ && training_thread_->joinable()) {
        training_thread_->join();
    }
}

TrainingMetrics TrainingManager::GetCurrentMetrics() const {
    std::lock_guard<std::mutex> lock(metrics_mutex_);
    return cached_metrics_;
}

bool TrainingManager::StartTrainingCommon(
    std::unique_ptr<TrainingExecutor> executor,
    int epochs,
    int batch_size,
    std::weak_ptr<TrainingPlotPanel> plot_panel,
    std::function<void(bool)> node_editor_callback,
    const std::string& task_name,
    const std::string& start_msg)
{
    // Caller has already verified !is_training_.load() and acquired
    // mutex_. This helper carries the common plumbing that used to
    // be duplicated across StartTraining{Legacy, Arrow, Parquet,
    // Image, Audio, Text} verbatim.
    is_training_.store(true);
    stop_requested_.store(false);
    const bool sequence_mode =
        executor && executor->GetConfig().sequence_batch.enabled;

    if (node_editor_callback) {
        node_editor_callback(true);
    }

    if (auto panel = plot_panel.lock()) {
        panel->Clear();
        panel->ShowCustomMetrics(sequence_mode);
        panel->SetTrainingState(true, 0, epochs, 0.0f, 0.0f);
        panel->SetVisible(true);
    }

    const auto now = std::chrono::system_clock::now().time_since_epoch();
    const auto run_ms =
        std::chrono::duration_cast<std::chrono::milliseconds>(now).count();
    const auto trace_snapshot = TrainingTraceCollector::Instance().Snapshot();
    if (!trace_snapshot.available || trace_snapshot.status != "running") {
        TrainingTraceCollector::Instance().StartRun(
            "train-" + std::to_string(run_ms));
    } else {
        TrainingTraceCollector::Instance().RecordRuntimeEvent(
            "TrainingSetup",
            "Training manager attached to existing preparation trace");
    }
    TrainingTraceCollector::Instance().RecordTaskProgress(
        0,
        task_name,
        "TrainingSetup",
        0.0f,
        start_msg,
        "running");

    // Tasks-panel progress tracker. Poll loop reads TrainingManager
    // state — the actual training work lives in TrainingThreadFunc.
    spdlog::info("TrainingManager: submitting task '{}'", task_name);
    current_task_id_.store(AsyncTaskManager::Instance().RunAsync(
        task_name,
        [](LambdaTask& task) {
            while (!task.ShouldStop()) {
                auto& mgr = TrainingManager::Instance();
                if (!mgr.IsTrainingActive()) {
                    break;
                }
                auto metrics = mgr.GetCurrentMetrics();
                float progress = static_cast<float>(metrics.current_epoch) /
                    std::max(1, metrics.total_epochs);
                task.ReportProgress(progress,
                    "Epoch " + std::to_string(metrics.current_epoch) + "/" +
                    std::to_string(metrics.total_epochs) +
                    " - Loss: " + std::to_string(metrics.train_loss).substr(0, 6));
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
            const auto final_metrics =
                TrainingManager::Instance().GetCurrentMetrics();
            if (final_metrics.terminal_status == "early_stopped") {
                const std::string reason = final_metrics.terminal_reason.empty()
                    ? "early stopping condition reached"
                    : final_metrics.terminal_reason;
                task.MarkCompleted("Early stopped: " + reason, "early_stopped");
            } else if (final_metrics.terminal_status == "cancelled") {
                task.MarkCompleted("Cancelled: user_cancelled", "cancelled");
            } else {
                task.MarkCompleted();
            }
        },
        nullptr,
        nullptr
    ));
    spdlog::info("TrainingManager: task '{}' submitted with id {}",
                 task_name, current_task_id_.load());

    if (on_training_start_) {
        on_training_start_(start_msg);
    }

    // Join any still-running prior training thread before replacing
    // it. Done here (inside the mutex) so two concurrent starts can't
    // race over training_thread_.
    if (training_thread_ && training_thread_->joinable()) {
        spdlog::info("TrainingManager: joining previous training thread before starting '{}'",
                     task_name);
        training_thread_->join();
    }

    spdlog::info("TrainingManager: creating training thread for '{}'", task_name);
    training_thread_ = std::make_unique<std::thread>(
        &TrainingManager::TrainingThreadFunc, this,
        std::move(executor), epochs, batch_size, plot_panel, node_editor_callback
    );

    spdlog::info("TrainingManager: Started {} ({} epochs, batch_size={})",
                 task_name, epochs, batch_size);
    return true;
}

bool TrainingManager::StartTraining(
    TrainingConfiguration config,
    DatasetHandle dataset,
    int epochs,
    int batch_size,
    std::weak_ptr<TrainingPlotPanel> plot_panel,
    std::function<void(bool)> node_editor_callback)
{
    // Check if already training
    if (is_training_.load()) {
        spdlog::warn("TrainingManager: Cannot start training - already training");
        return false;
    }

    std::lock_guard<std::mutex> lock(mutex_);

    // Double-check after acquiring lock
    if (is_training_.load()) {
        return false;
    }

    NormalizeTrainingNumWorkers(config, "TrainingManager");

    auto executor = std::make_unique<TrainingExecutor>(std::move(config), dataset);
    return StartTrainingCommon(
        std::move(executor), epochs, batch_size, plot_panel,
        std::move(node_editor_callback),
        "Training Model", "Training from Node Graph");
}

bool TrainingManager::StartTrainingArrow(
    TrainingConfiguration config,
    std::shared_ptr<ArrowDataset> arrow_dataset,
    const std::string& label_column,
    int epochs,
    int batch_size,
    std::weak_ptr<TrainingPlotPanel> plot_panel,
    std::function<void(bool)> node_editor_callback)
{
    // Check if already training
    if (is_training_.load()) {
        spdlog::warn("TrainingManager: Cannot start training - already training");
        return false;
    }

    if (!arrow_dataset) {
        spdlog::error("TrainingManager: Arrow dataset is null");
        return false;
    }

    std::lock_guard<std::mutex> lock(mutex_);

    // Double-check after acquiring lock
    if (is_training_.load()) {
        return false;
    }

    // Update input size from actual data
    size_t num_cols = arrow_dataset->GetNumColumns();
    size_t num_rows = arrow_dataset->GetNumRows();

    // Input size = all columns except label
    // ArrowDatasetBatcher auto-detects label columns, so always reserve one column for label
    // when dataset has multiple columns (typical ML dataset structure).
    //
    // Phase 4 Time-Series: trust the GraphCompiler's input_size override.
    // For TS graphs GraphCompiler sets input_size from the TimeSeriesWindow
    // operator's input_width param. The materialized Arrow table ALSO has
    // an extra `__partition__` metadata column, so `num_cols - 1` would
    // double-count it as a feature and build a Linear layer of the wrong
    // size (crash at first forward pass due to dimension mismatch with the
    // batch tensor, which correctly excludes both label AND __partition__).
    const auto input_resolution =
        ResolveTabularTrainingInputSize(config, num_cols);
    config.input_size = input_resolution.input_size;

    if (input_resolution.used_compiled_override) {
        spdlog::info("TrainingManager: Arrow dataset has {} rows, {} cols, "
                     "input_size={} (from GraphCompiler's TimeSeriesWindow override)",
                     num_rows, num_cols, config.input_size);
    } else if (input_resolution.has_separate_label_column) {
        spdlog::info("TrainingManager: Arrow dataset has {} rows, {} cols, input_size={} (assuming 1 label column)",
                     num_rows, num_cols, config.input_size);
    } else {
        spdlog::warn("TrainingManager: Arrow dataset has only {} column - no separate label column", num_cols);
    }

    NormalizeTrainingNumWorkers(config, "TrainingManager");
    spdlog::info("TrainingManager: resolving Arrow class-weight/balancing hints");
    TryApplyBalancedClassWeightsFromArrowTable(
        config,
        arrow_dataset ? arrow_dataset->GetArrowTable() : nullptr,
        label_column,
        /*partition_column=*/"",
        "TrainingManager Arrow");
    spdlog::info("TrainingManager: Arrow class-weight/balancing hint resolution complete");

    spdlog::info("TrainingManager: creating Arrow TrainingExecutor");
    auto executor = std::make_unique<TrainingExecutor>(std::move(config), arrow_dataset, label_column);
    spdlog::info("TrainingManager: Arrow TrainingExecutor created");
    return StartTrainingCommon(
        std::move(executor), epochs, batch_size, plot_panel,
        std::move(node_editor_callback),
        "Training Model (Arrow)", "Training from Arrow Dataset");
}

bool TrainingManager::StartTrainingParquet(
    TrainingConfiguration config,
