    else if (change_type == StatChangeType::Bad) value_color = Colors::Red;
    else if (change_type == StatChangeType::Warn) value_color = Colors::Gold;

    ImGui::TextColored(value_color, "%s", value.c_str());
    ImGui::PopFont();

    // Change indicator
